package app.codex.f5voice.compat.com.android.recovery;
import android.app.Activity;import android.os.*;import android.graphics.Color;import android.graphics.drawable.*;import android.content.res.ColorStateList;import android.widget.*;
public final class MainActivity extends Activity {
 private final Handler main=new Handler();private TextView status;private final Runnable update=new Runnable(){public void run(){status.setText(RecoveryState.prefs(MainActivity.this).getString("status","尚未启用"));main.postDelayed(this,1000);}};
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(0xFFF5F6FA);v.setPadding(0,dp(7),0,dp(7));return v;}
 private GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(30));return g;}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(18);b.setAllCaps(false);StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},bg(0xFFF5F6FA));d.addState(new int[]{android.R.attr.state_pressed},bg(0xFFF5F6FA));d.addState(new int[]{},bg(0xFF35435A));b.setBackground(d);b.setTextColor(new ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[]{android.R.attr.state_pressed},new int[]{}},new int[]{0xFF19283F,0xFF19283F,0xFFF5F6FA}));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(p);return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(40),dp(24),dp(40),dp(24));root.setBackgroundColor(0xFF19283F);root.addView(text("VoxKey 恢复助手",27));status=text("",18);root.addView(status);root.addView(text("开机或唤醒后，恢复 VoxKey 输入法和语音键服务。\n主动切换普通输入法后，本次使用期间不会强行切回。\n本助手不录音、不联网；停用后不再自动恢复。",15));Button enable=button("启用自动恢复",()->RecoveryState.enable(this));root.addView(enable);root.addView(button("立即恢复 VoxKey",()->{if(!RecoveryState.enabled(this))RecoveryState.enable(this);else RecoveryState.manual(this);}));root.addView(button("停用自动恢复",()->RecoveryState.disable(this)));root.addView(button("返回",()->finish()));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);enable.requestFocus();}
 @Override public void onResume(){super.onResume();main.post(update);}
 @Override public void onPause(){main.removeCallbacks(update);super.onPause();}
}
